  1→ // @ts-nocheck
  2→// deno-lint-ignore-file no-explicit-any
  3→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  4→import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
  5→
  6→const corsHeaders = {
  7→  "Access-Control-Allow-Origin": "*",
  8→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, webhook-id, webhook-signature, webhook-timestamp",
  9→};
 10→
 11→Deno.serve(async (req) => {
 12→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 13→
 14→  try {
 15→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 16→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 17→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
 18→    const WEBHOOK_KEY = Deno.env.get("DODO_PAYMENTS_WEBHOOK_KEY") || Deno.env.get("DODO_PAYMENTS_WEBHOOK_SECRET");
 19→
 20→    if (!DODO_API_KEY) {
 21→      console.error("DODO_PAYMENTS_API_KEY is not configured");
 22→      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
 23→    }
 24→    if (!WEBHOOK_KEY) {
 25→      console.error("DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured");
 26→      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
 27→    }
 28→
 29→    const rawBody = await req.text();
 30→    const webhookHeaders = {
 31→      "webhook-id": req.headers.get("webhook-id") || "",
 32→      "webhook-signature": req.headers.get("webhook-signature") || "",
 33→      "webhook-timestamp": req.headers.get("webhook-timestamp") || "",
 34→    };
 35→
 36→    const dodo = new DodoPayments({
 37→      bearerToken: DODO_API_KEY,
 38→      webhookKey: WEBHOOK_KEY,
 39→    });
 40→
 41→    let unwrapped: any;
 42→    try {
 43→      unwrapped = dodo.webhooks.unwrap(rawBody, { headers: webhookHeaders });
 44→    } catch (e) {
 45→      console.error("Invalid webhook signature", e);
 46→      return new Response("Invalid signature", { status: 401, headers: corsHeaders });
 47→    }
 48→
 49→    const eventType: string = unwrapped.type || "unknown";
 50→    const payload: Record<string, unknown> = unwrapped.data || {};
 51→    const webhookId = webhookHeaders["webhook-id"];
 52→
 53→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 54→
 55→    // Idempotency: skip if we've already processed this exact webhook-id
 56→    if (webhookId) {
 57→      const { data: dupList } = await supabase
 58→        .from("subscription_webhooks")
 59→        .select("id")
 60→        .eq("gateway", "dodo")
 61→        .eq("webhook_id", webhookId)
 62→        .limit(1);
 63→      if (dupList && dupList.length > 0) {
 64→        console.log(`Duplicate webhook ${webhookId}, skipping`);
 65→        return new Response("OK", { status: 200, headers: corsHeaders });
 66→      }
 67→    }
 68→
 69→    const subscriptionIdForLog = (payload["subscription_id"] as string | undefined) || null;
 70→
 71→    // Log the event (unprocessed)
 72→    const logInsert = await supabase
 73→      .from("subscription_webhooks")
 74→      .insert({
 75→        event_type: eventType,
 76→        payload: unwrapped,
 77→        gateway: "dodo",
 78→        processed: false,
 79→        dodo_subscription_id: subscriptionIdForLog,
 80→        webhook_id: webhookId || null,
 81→      })
 82→      .select("id")
 83→      .single();
 84→
 85→    const logId: string | null = logInsert.data?.id ?? null;
 86→
 87→    async function markProcessed(userId?: string | null) {
 88→      if (!logId) return;
 89→      await supabase
 90→        .from("subscription_webhooks")
 91→        .update({ processed: true, user_id: userId ?? null })
 92→        .eq("id", logId);
 93→    }
 94→
 95→    // Prefer correlation via metadata.local_payment_id (set at checkout creation)
 96→    const meta = (payload["metadata"] as Record<string, string> | undefined) || {};
 97→    const localPaymentId = (meta["local_payment_id"] as string | undefined) || null;
 98→
 99→    if (eventType === "payment.succeeded" || eventType === "payment_succeeded") {
100→      const paymentId = (payload["payment_id"] as string | undefined) || null;
101→
102→      let paymentRow: any = null;
103→      if (localPaymentId) {
104→        const { data } = await supabase.from("payments").select("*").eq("id", localPaymentId).single();
105→        paymentRow = data;
106→      } else if (paymentId) {
107→        const { data } = await supabase.from("payments").select("*").eq("dodo_payment_id", paymentId).single();
108→        paymentRow = data;
109→      }
110→
111→      if (paymentRow) {
112→        // Atomic status transition: only the first delivery wins (idempotent on retries)
113→        const { data: paidUpdate } = await supabase
114→          .from("payments")
115→          .update({
116→            status: "paid",
117→            ...(paymentId && !paymentRow.dodo_payment_id ? { dodo_payment_id: paymentId } : {}),
118→          })
119→          .eq("id", paymentRow.id)
120→          .neq("status", "paid")
121→          .select("id")
122→          .maybeSingle();
123→        const newlyPaid = !!paidUpdate;
124→
125→        if (newlyPaid) {
126→          // Increment credits once (idempotent on status transition)
127→          // Plan purchase → subscription_credits; pack purchase → topup_credits
128→          const creditField = paymentRow.plan_id ? "subscription_credits" : "topup_credits";
129→          const { data: profile } = await supabase
130→            .from("profiles")
131→            .select("credits, subscription_credits, topup_credits")
132→            .eq("user_id", paymentRow.user_id)
133→            .single();
134→
135→          if (profile) {
136→            await supabase
137→              .from("profiles")
138→              .update({
139→                [creditField]: ((profile as any)[creditField] ?? 0) + paymentRow.credits_purchased,
140→                credits: (profile.credits ?? 0) + paymentRow.credits_purchased,
141→              })
142→              .eq("user_id", paymentRow.user_id);
143→          }
144→
145→          // Activate plan if applicable
146→          if (paymentRow.plan_id) {
147→            const { data: plan } = await supabase
148→              .from("plans")
149→              .select("name, billing_type")
150→              .eq("id", paymentRow.plan_id)
151→              .single();
152→
153→            if (plan) {
154→              const endsAt = new Date();
155→              if (plan.billing_type === "yearly") {
156→                endsAt.setFullYear(endsAt.getFullYear() + 1);
157→              } else {
158→                endsAt.setMonth(endsAt.getMonth() + 1);
159→              }
160→              await supabase
161→                .from("profiles")
162→                .update({
163→                  plan: plan.name,
164→                  subscription_ends_at: endsAt.toISOString(),
165→                  dodo_subscription_id: (payload["subscription_id"] as string | undefined) || null,
166→                })
167→                .eq("user_id", paymentRow.user_id);
168→            }
169→          }
170→        }
171→
172→        await markProcessed(paymentRow.user_id);
173→      }
174→    } else if (eventType === "payment.failed" || eventType === "payment_failed") {
175→      const paymentId = (payload["payment_id"] as string | undefined) || null;
176→      if (localPaymentId) {
177→        await supabase
178→          .from("payments")
179→          .update({ status: "failed", dodo_payment_id: paymentId })
180→          .eq("id", localPaymentId);
181→      } else if (paymentId) {
182→        await supabase.from("payments").update({ status: "failed" }).eq("dodo_payment_id", paymentId);
183→      }
184→      await markProcessed(null);
185→    } else if (eventType === "subscription.renewed" || eventType === "subscription_renewed") {
186→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
187→      if (subscriptionId) {
188→        const { data: profile } = await supabase
189→          .from("profiles")
190→          .select("user_id, plan, credits, subscription_credits")
191→          .eq("dodo_subscription_id", subscriptionId)
192→          .single();
193→
194→        if (profile) {
195→          const { data: plan } = await supabase
196→            .from("plans")
197→            .select("credits, billing_type")
198→            .eq("name", profile.plan)
199→            .single();
200→
201→          if (plan) {
202→            const endsAt = new Date();
203→            if (plan.billing_type === "yearly") {
204→              endsAt.setFullYear(endsAt.getFullYear() + 1);
205→            } else {
206→              endsAt.setMonth(endsAt.getMonth() + 1);
207→            }
208→            // Renewal resets subscription_credits to plan amount (monthly allowance, not cumulative).
209→            // Only add the net delta to total credits so topup_credits and total stay accurate.
210→            const currentSub = (profile as any).subscription_credits ?? 0;
211→            const subDelta = plan.credits - currentSub;
212→            await supabase
213→              .from("profiles")
214→              .update({
215→                subscription_credits: plan.credits,
216→                credits: (profile.credits ?? 0) + subDelta,
217→                subscription_ends_at: endsAt.toISOString(),
218→              })
219→              .eq("user_id", profile.user_id);
220→          }
221→        }
222→      }
223→      await markProcessed(null);
224→    } else if (
225→      eventType === "subscription.cancelled" ||
226→      eventType === "subscription_cancelled" ||
227→      eventType === "subscription.on_hold" ||
228→      eventType === "subscription.failed"
229→    ) {
230→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
231→      if (subscriptionId) {
232→        // For on_hold/failed: downgrade immediately; for cancelled, let expiry task handle downgrade.
233→        if (eventType.includes("on_hold") || eventType.includes("failed")) {
234→          await supabase
235→            .from("profiles")
236→            .update({
237→              plan: "free",
238→              dodo_subscription_id: null,
239→              subscription_ends_at: null,
240→            })
241→            .eq("dodo_subscription_id", subscriptionId);
242→        }
243→      }
244→      await markProcessed(null);
245→    } else if (eventType === "subscription.active" || eventType === "subscription_active") {
246→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
247→      if (subscriptionId && localPaymentId) {
248→        const { data: payment } = await supabase.from("payments").select("user_id").eq("id", localPaymentId).single();
249→        if (payment) {
250→          await supabase.from("profiles").update({ dodo_subscription_id: subscriptionId }).eq("user_id", payment.user_id);
251→          await markProcessed(payment.user_id);
252→        }
253→      }
254→    }
255→
256→    return new Response("OK", { status: 200, headers: corsHeaders });
257→  } catch (err) {
258→    console.error("dodo-webhook error:", err);
259→    return new Response("Internal error", { status: 500, headers: corsHeaders });
260→  }
261→});
