  1→// @ts-nocheck
  2→// deno-lint-ignore-file no-explicit-any
  3→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  4→
  5→const corsHeaders = {
  6→  "Access-Control-Allow-Origin": "*",
  7→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  8→};
  9→
 10→const PAID_STATUSES = new Set(["paid", "completed", "succeeded", "success"]);
 11→const FAILED_STATUSES = new Set(["failed", "cancelled", "canceled", "dismissed"]);
 12→
 13→const toLocalStatus = (raw: string | null | undefined) => {
 14→  const normalized = (raw || "").toLowerCase();
 15→  if (PAID_STATUSES.has(normalized)) return "paid";
 16→  if (FAILED_STATUSES.has(normalized)) return normalized === "canceled" ? "cancelled" : normalized;
 17→  return null;
 18→};
 19→
 20→const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
 21→
 22→Deno.serve(async (req) => {
 23→  if (req.method === "OPTIONS") {
 24→    return new Response(null, { headers: corsHeaders });
 25→  }
 26→
 27→  try {
 28→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
 29→    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY");
 30→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
 31→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
 32→    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
 33→
 34→    if (!SUPABASE_URL || !SUPABASE_ANON_KEY || !SUPABASE_SERVICE_ROLE_KEY || !DODO_API_KEY) {
 35→      return new Response(JSON.stringify({ error: "Server configuration error" }), {
 36→        status: 500,
 37→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 38→      });
 39→    }
 40→
 41→    const authHeader = req.headers.get("Authorization");
 42→    if (!authHeader) {
 43→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 44→        status: 401,
 45→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 46→      });
 47→    }
 48→
 49→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
 50→      global: { headers: { Authorization: authHeader } },
 51→    });
 52→
 53→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
 54→    if (userError || !user) {
 55→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 56→        status: 401,
 57→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 58→      });
 59→    }
 60→
 61→    const body = await req.json().catch(() => ({}));
 62→    const paymentId = typeof body.payment_id === "string" ? body.payment_id : null;
 63→    const localPaymentId = typeof body.local_payment_id === "string" ? body.local_payment_id : null;
 64→    const checkoutSessionIdInput = typeof body.checkout_session_id === "string" ? body.checkout_session_id : null;
 65→
 66→    if (!paymentId && !localPaymentId && !checkoutSessionIdInput) {
 67→      return new Response(JSON.stringify({ error: "payment_id, local_payment_id, or checkout_session_id is required" }), {
 68→        status: 400,
 69→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 70→      });
 71→    }
 72→
 73→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 74→
 75→    const baseUrl = DODO_ENV === "live_mode"
 76→      ? "https://live.dodopayments.com"
 77→      : "https://test.dodopayments.com";
 78→
 79→    // ── Step 1: find local payment record ────────────────────────────────────
 80→    let paymentRow: Record<string, any> | null = null;
 81→
 82→    if (localPaymentId) {
 83→      const { data } = await supabase
 84→        .from("payments")
 85→        .select("*")
 86→        .eq("id", localPaymentId)
 87→        .eq("user_id", user.id)
 88→        .maybeSingle();
 89→      paymentRow = data || null;
 90→    }
 91→
 92→    if (!paymentRow && checkoutSessionIdInput) {
 93→      const { data } = await supabase
 94→        .from("payments")
 95→        .select("*")
 96→        .eq("dodo_checkout_session_id", checkoutSessionIdInput)
 97→        .eq("user_id", user.id)
 98→        .maybeSingle();
 99→      paymentRow = data || null;
100→    }
101→
102→    if (!paymentRow && paymentId) {
103→      const { data } = await supabase
104→        .from("payments")
105→        .select("*")
106→        .eq("dodo_payment_id", paymentId)
107→        .eq("user_id", user.id)
108→        .maybeSingle();
109→      paymentRow = data || null;
110→    }
111→
112→    if (!paymentRow) {
113→      return new Response(JSON.stringify({ error: "Payment record not found for current user" }), {
114→        status: 404,
115→        headers: { ...corsHeaders, "Content-Type": "application/json" },
116→      });
117→    }
118→
119→    // ── Step 2: if already paid in DB (webhook beat us here) — return now ───
120→    if (paymentRow.status === "paid") {
121→      return new Response(JSON.stringify({
122→        success: true,
123→        local_payment_id: paymentRow.id,
124→        dodo_payment_id: paymentRow.dodo_payment_id,
125→        checkout_session_id: paymentRow.dodo_checkout_session_id,
126→        dodo_status: "paid",
127→        local_status: "paid",
128→        credits_added: false,
129→      }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
130→    }
131→
132→    // ── Step 3: find the Dodo payment_id to query ────────────────────────────
133→    // For subscriptions Dodo doesn't include payment_id in the redirect URL,
134→    // so we need to search by checkout_session_id on Dodo's payments list API.
135→    let dodoPayment: Record<string, any> | null = null;
136→
137→    const dodoPaymentIdToFetch = paymentId || paymentRow.dodo_payment_id || null;
138→    const sessionIdToSearch = checkoutSessionIdInput || paymentRow.dodo_checkout_session_id || null;
139→
140→    // ── Step 3a: direct fetch by payment_id if we have it ────────────────────
141→    if (dodoPaymentIdToFetch) {
142→      const res = await fetch(`${baseUrl}/payments/${encodeURIComponent(dodoPaymentIdToFetch)}`, {
143→        headers: { Authorization: `Bearer ${DODO_API_KEY}`, "Content-Type": "application/json" },
144→      });
145→      if (res.ok) {
146→        dodoPayment = await res.json();
147→        console.log("Fetched Dodo payment by ID:", dodoPayment?.payment_id, "status:", dodoPayment?.status);
148→      } else {
149→        console.error("Dodo payment fetch by ID failed:", res.status, await res.text());
150→      }
151→    }
152→
153→    // ── Step 3b: search by checkout_session_id (subscription case) ───────────
154→    // Dodo payments list supports ?checkout_session_id= filter
155→    if (!dodoPayment && sessionIdToSearch) {
156→      const listRes = await fetch(`${baseUrl}/payments?checkout_session_id=${encodeURIComponent(sessionIdToSearch)}&page_size=5`, {
157→        headers: { Authorization: `Bearer ${DODO_API_KEY}`, "Content-Type": "application/json" },
158→      });
159→      if (listRes.ok) {
160→        const listData = await listRes.json();
161→        // Response is either { items: [...] } or an array directly
162→        const items: any[] = Array.isArray(listData) ? listData : (listData.items || listData.data || []);
163→        if (items.length > 0) {
164→          dodoPayment = items[0];
165→          console.log("Found Dodo payment via session search:", dodoPayment?.payment_id, "status:", dodoPayment?.status);
166→        } else {
167→          console.log("No Dodo payment found for session yet, will retry");
168→        }
169→      } else {
170→        console.warn("Dodo payment list by session failed:", listRes.status, await listRes.text());
171→      }
172→    }
173→
174→    // ── Step 3c: retry loop — subscriptions take a few seconds to register ───
175→    // If we still have no Dodo payment, retry up to 5 times with 2s gaps
176→    if (!dodoPayment && sessionIdToSearch) {
177→      for (let attempt = 1; attempt <= 5; attempt++) {
178→        await sleep(2000);
179→        console.log(`Retry ${attempt}/5 polling Dodo for session ${sessionIdToSearch}`);
180→
181→        const listRes = await fetch(`${baseUrl}/payments?checkout_session_id=${encodeURIComponent(sessionIdToSearch)}&page_size=5`, {
182→          headers: { Authorization: `Bearer ${DODO_API_KEY}`, "Content-Type": "application/json" },
183→        });
184→        if (listRes.ok) {
185→          const listData = await listRes.json();
186→          const items: any[] = Array.isArray(listData) ? listData : (listData.items || listData.data || []);
187→          if (items.length > 0) {
188→            dodoPayment = items[0];
189→            console.log("Found payment on retry", attempt, ":", dodoPayment?.payment_id, dodoPayment?.status);
190→            break;
191→          }
192→        }
193→
194→        // Also check local DB — webhook may have arrived during our sleep
195→        const { data: refreshed } = await supabase
196→          .from("payments")
197→          .select("*")
198→          .eq("id", paymentRow.id)
199→          .single();
200→        if (refreshed?.status === "paid") {
201→          console.log("Webhook marked payment paid during retry loop");
202→          return new Response(JSON.stringify({
203→            success: true,
204→            local_payment_id: refreshed.id,
205→            dodo_payment_id: refreshed.dodo_payment_id,
206→            checkout_session_id: refreshed.dodo_checkout_session_id,
207→            dodo_status: "paid",
208→            local_status: "paid",
209→            credits_added: false,
210→          }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
211→        }
212→      }
213→    }
214→
215→    // ── Step 4: if we still have no Dodo payment data, return pending ─────────
216→    if (!dodoPayment) {
217→      console.warn("Could not fetch Dodo payment after retries — returning pending");
218→      return new Response(JSON.stringify({
219→        success: true,
220→        local_payment_id: paymentRow.id,
221→        dodo_status: null,
222→        local_status: paymentRow.status, // 'created' — frontend will keep polling
223→        credits_added: false,
224→      }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
225→    }
226→
227→    // ── Step 5: store dodo_payment_id if we just discovered it ───────────────
228→    const resolvedPaymentId = dodoPayment.payment_id || dodoPayment.id || dodoPaymentIdToFetch || null;
229→    const resolvedSessionId = dodoPayment.checkout_session_id || sessionIdToSearch || null;
230→    const resolvedSubscriptionId = dodoPayment.subscription_id || null;
231→
232→    const updatePayload: Record<string, any> = {};
233→    if (resolvedPaymentId && paymentRow.dodo_payment_id !== resolvedPaymentId) updatePayload.dodo_payment_id = resolvedPaymentId;
234→    if (resolvedSessionId && paymentRow.dodo_checkout_session_id !== resolvedSessionId) updatePayload.dodo_checkout_session_id = resolvedSessionId;
235→    if (Object.keys(updatePayload).length > 0) {
236→      await supabase.from("payments").update(updatePayload).eq("id", paymentRow.id);
237→    }
238→
239→    // ── Step 6: process paid status ──────────────────────────────────────────
240→    const dodoStatus = toLocalStatus(dodoPayment.status);
241→    let becamePaid = false;
242→    let finalStatus = paymentRow.status;
243→
244→    if (dodoStatus === "paid") {
245→      // Atomic update: only fires if not already paid (idempotent)
246→      const { data: paidUpdate } = await supabase
247→        .from("payments")
248→        .update({
249→          status: "paid",
250→          ...(resolvedPaymentId ? { dodo_payment_id: resolvedPaymentId } : {}),
251→          ...(resolvedSessionId ? { dodo_checkout_session_id: resolvedSessionId } : {}),
252→        })
253→        .eq("id", paymentRow.id)
254→        .neq("status", "paid")
255→        .select("id")
256→        .maybeSingle();
257→
258→      becamePaid = !!paidUpdate;
259→      finalStatus = "paid";
260→
261→      if (becamePaid) {
262→        // Add credits to the correct bucket:
263→        // - plan purchase → subscription_credits (reset monthly)
264→        // - pack purchase → topup_credits (never expire)
265→        const creditField = paymentRow.plan_id ? "subscription_credits" : "topup_credits";
266→        const { data: profile } = await supabase
267→          .from("profiles")
268→          .select("credits, subscription_credits, topup_credits")
269→          .eq("user_id", paymentRow.user_id)
270→          .single();
271→
272→        if (profile) {
273→          await supabase
274→            .from("profiles")
275→            .update({
276→              [creditField]: (profile[creditField] ?? 0) + paymentRow.credits_purchased,
277→              credits: (profile.credits ?? 0) + paymentRow.credits_purchased,
278→            })
279→            .eq("user_id", paymentRow.user_id);
280→        }
281→
282→        // Activate subscription if this is a plan payment
283→        if (paymentRow.plan_id) {
284→          const { data: plan } = await supabase
285→            .from("plans")
286→            .select("name, billing_type")
287→            .eq("id", paymentRow.plan_id)
288→            .single();
289→
290→          if (plan) {
291→            const endsAt = new Date();
292→            if (plan.billing_type === "yearly") {
293→              endsAt.setFullYear(endsAt.getFullYear() + 1);
294→            } else {
295→              endsAt.setMonth(endsAt.getMonth() + 1);
296→            }
297→
298→            const profileUpdate: Record<string, any> = {
299→              plan: plan.name,
300→              subscription_ends_at: endsAt.toISOString(),
301→            };
302→            // Store subscription_id if Dodo provided it (may come later via webhook if missing now)
303→            if (resolvedSubscriptionId) {
304→              profileUpdate.dodo_subscription_id = resolvedSubscriptionId;
305→            }
306→
307→            await supabase
308→              .from("profiles")
309→              .update(profileUpdate)
310→              .eq("user_id", paymentRow.user_id);
311→
312→            console.log("Subscription activated for user:", paymentRow.user_id, "plan:", plan.name, "subscription_id:", resolvedSubscriptionId || "(pending webhook)");
313→          }
314→        }
315→      }
316→    } else if (dodoStatus && dodoStatus !== paymentRow.status) {
317→      await supabase
318→        .from("payments")
319→        .update({ status: dodoStatus })
320→        .eq("id", paymentRow.id);
321→      finalStatus = dodoStatus;
322→    }
323→
324→    return new Response(JSON.stringify({
325→      success: true,
326→      local_payment_id: paymentRow.id,
327→      dodo_payment_id: resolvedPaymentId,
328→      checkout_session_id: resolvedSessionId,
329→      dodo_status: dodoPayment.status || null,
330→      local_status: finalStatus,
331→      credits_added: becamePaid,
332→    }), {
333→      headers: { ...corsHeaders, "Content-Type": "application/json" },
334→    });
335→
336→  } catch (err: unknown) {
337→    console.error("verify-dodo-payment error:", err);
338→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
339→      status: 500,
340→      headers: { ...corsHeaders, "Content-Type": "application/json" },
341→    });
342→  }
343→});
