 11→};
 12→
 13→Deno.serve(async (req) => {
 14→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 15→
 16→  try {
 17→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 18→    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
 19→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 20→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
 21→    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
 22→
 23→    if (!DODO_API_KEY) {
 24→      return new Response(
 25→        JSON.stringify({ error: "Dodo Payments API key not configured" }),
 26→        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
 27→      );
 28→    }
 29→
 30→    // Authenticate user
 31→    const authHeader = req.headers.get("Authorization");
 32→    if (!authHeader) {
 33→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 34→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 35→      });
 36→    }
 37→
 38→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
 39→      global: { headers: { Authorization: authHeader } },
 40→    });
 41→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
 42→    if (userError || !user) {
 43→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
 44→        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 45→      });
 46→    }
 47→
 48→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 49→    const body = await req.json();
 50→    const { topup_amount, plan_id, return_url } = body as Record<string, unknown>;
 51→
 52→    if (!topup_amount && !plan_id) {
 53→      return new Response(JSON.stringify({ error: "topup_amount or plan_id required" }), {
 54→        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 55→      });
 56→    }
 57→
 58→    let productId: string;
 59→    let amount: number;
 60→    let credits: number;
 61→    let currency = "USD";
 62→    let itemName: string;
 63→    let itemType: "topup" | "plan";
 64→    let itemId: string | null = null;
 65→
 66→    if (topup_amount) {
 67→      // ─── WALLET TOP-UP FLOW ───
 68→      const topupNum = Number(topup_amount);
 69→      if (isNaN(topupNum) || topupNum <= 0) {
 70→        return new Response(JSON.stringify({ error: "Invalid topup_amount" }), {
 71→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 72→        });
 73→      }
 74→
 75→      // Get platform config for min amount, per-resume cost, and dodo product id
 76→      const { data: config, error: configError } = await supabase
 77→        .from("platform_config")
 78→        .select("topup_min_amount, payg_per_resume_cost, topup_dodo_product_id")
 79→        .limit(1)
 80→        .single();
 81→
 82→      if (configError || !config) {
 83→        return new Response(JSON.stringify({ error: "Platform config not found" }), {
 84→          status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
 85→        });
 86→      }
 87→
 88→      const minAmount = config.topup_min_amount ?? 1;
 89→      if (topupNum < minAmount) {
 90→        return new Response(JSON.stringify({ error: `Minimum top-up amount is $${minAmount}` }), {
 91→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 92→        });
 93→      }
 94→
 95→      if (!config.topup_dodo_product_id) {
 96→        return new Response(JSON.stringify({ error: "Wallet top-up not configured. Admin must create the Dodo product first." }), {
 97→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
 98→        });
 99→      }
100→
101→      const perResumeCost = config.payg_per_resume_cost ?? 0.07;
102→      credits = Math.floor(topupNum / perResumeCost);
103→      if (credits < 1) {
104→        return new Response(JSON.stringify({ error: "Amount too small to purchase any credits" }), {
105→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
106→        });
107→      }
108→
109→      productId = config.topup_dodo_product_id;
110→      amount = Math.round(topupNum * 100); // cents
111→      itemName = `Wallet Top-Up $${topupNum}`;
112→      itemType = "topup";
113→    } else {
114→      // ─── PLAN SUBSCRIPTION FLOW (unchanged) ───
115→      const { data: plan, error } = await supabase
116→        .from("plans")
117→        .select("*")
118→        .eq("id", plan_id)
119→        .eq("active", true)
120→        .single();
121→      if (error || !plan) {
122→        return new Response(JSON.stringify({ error: "Plan not found or inactive" }), {
123→          status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
124→        });
125→      }
126→      if (!plan.dodo_product_id) {
127→        return new Response(JSON.stringify({ error: "This plan is not configured for Dodo Payments. Add a Dodo Product ID in admin." }), {
128→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
129→        });
130→      }
131→      productId = plan.dodo_product_id;
132→      amount = Math.round(plan.price * 100);
133→      credits = plan.credits;
134→      itemName = plan.name;
135→      itemType = "plan";
136→      itemId = String(plan_id);
137→    }
138→
139→    // Build return URL
140→    const baseReturnUrl =
141→      (typeof return_url === "string" && return_url) ||
142→      `${req.headers.get("origin") || "https://rankora.co"}/payment/callback`;
143→
144→    // 1) Create local payment record
145→    const insertPayload: any = {
146→      user_id: user.id,
147→      amount,
148→      currency,
149→      credits_purchased: credits,
150→      status: "created",
151→      payment_gateway: "dodo",
152→    };
153→    if (itemType === "plan" && itemId) {
154→      insertPayload.plan_id = itemId;
155→    }
156→
157→    const insertRes = await supabase
158→      .from("payments")
159→      .insert(insertPayload)
160→      .select("id")
161→      .single();
162→
163→    if (insertRes.error || !insertRes.data) {
164→      console.error("Failed to create local payment record:", insertRes.error?.message);
165→      return new Response(JSON.stringify({ error: "Failed to create local payment record" }), {
166→        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
167→      });
168→    }
169→
170→    const localPaymentId = insertRes.data.id as string;
171→    const returnUrlWithLocalPaymentId = `${baseReturnUrl}${baseReturnUrl.includes("?") ? "&" : "?"}local_payment_id=${encodeURIComponent(localPaymentId)}`;
172→
173→    // 2) Create Dodo Checkout Session
174→    const isLive = DODO_ENV === "live_mode";
175→    const client = new DodoPayments({
176→      bearerToken: DODO_API_KEY,
177→      baseURL: isLive
178→        ? "https://live.dodopayments.com"
179→        : "https://test.dodopayments.com",
180→    });
181→
182→    const cartItem: any = { product_id: productId, quantity: 1 };
183→    if (itemType === "topup") {
184→      cartItem.amount = amount; // dynamic amount in cents for PWYW product
185→    }
186→
187→    const session = await client.checkoutSessions.create({
188→      product_cart: [cartItem],
189→      customer: {
190→        email: user.email ?? "",
191→        name: user.email?.split("@")[0] || "Customer",
192→      },
193→      billing_address: {
194→        street: "NA",
195→        city: "NA",
196→        state: "NA",
197→        country: "US",
198→        zipcode: "00000",
199→      },
200→      return_url: returnUrlWithLocalPaymentId,
201→      metadata: {
202→        local_payment_id: localPaymentId,
203→        user_id: user.id,
204→        item_type: itemType,
205→        item_id: itemId || "",
206→        item_name: itemName,
207→        credits: String(credits),
208→      } as Record<string, string>,
209→    });
210→
211→    // 3) Persist the Dodo checkout session id
212→    if ((session as Record<string, unknown>).session_id) {
213→      await supabase
214→        .from("payments")
215→        .update({ dodo_checkout_session_id: (session as Record<string, string>).session_id })
216→        .eq("id", localPaymentId);
217→    }
218→
219→    return new Response(
220→      JSON.stringify({
221→        checkout_url: (session as Record<string, string>).checkout_url,
222→        checkout_session_id: (session as Record<string, string>).session_id,
223→        payment_id: localPaymentId,
224→      }),
225→      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
226→    );
227→  } catch (err: unknown) {
228→    console.error("create-dodo-checkout error:", err);
229→    return new Response(
230→      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
231→      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
232→    );
233→  }
234→});
