 81→serve(async (req) => {
 82→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 83→
 84→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 85→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
