127→    }
128→    if (template_key === "resume_received" && !config.email_notify_resume_received) {
129→      return new Response(JSON.stringify({ skipped: true, reason: "Resume received notifications disabled" }), {
130→        status: 200,
131→        headers: { ...corsHeaders, "Content-Type": "application/json" },
132→      });
133→    }
134→
135→    // Load template
136→    const { data: template, error: tplError } = await supabase
137→      .from("email_templates")
138→      .select("subject, body_html")
139→      .eq("template_key", template_key)
140→      .single();
141→
142→    if (tplError || !template) {
