  9→/** Extract a usable email from various formats */
 10→function extractEmail(raw: string): string {
 11→  // Handle "Name <email@domain>" format
 12→  const match = raw.match(/<([^>]+)>/);
 13→  return (match ? match[1] : raw).trim().toLowerCase();
 14→}
