 16→serve(async (req) => {
 17→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 18→
 19→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 20→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 21→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 22→
 23→  // Helper to log and respond
 24→  const logAndRespond = async (
 25→    status: number,
 26→    logData: { sender?: string | null; recipient?: string | null; user_id?: string | null; job_id?: string | null; status: string; error_message?: string | null; attachments_count?: number; resumes_created?: number },
 27→    responseBody: Record<string, unknown>
 28→  ) => {
 29→    try {
 30→      await supabase.from("email_ingest_logs").insert({
 31→        sender: logData.sender || null,
 32→        recipient: logData.recipient || null,
 33→        user_id: logData.user_id || null,
 34→        job_id: logData.job_id || null,
 35→        status: logData.status,
 36→        error_message: logData.error_message || null,
 37→        attachments_count: logData.attachments_count || 0,
 38→        resumes_created: logData.resumes_created || 0,
 39→      });
 40→    } catch (e) {
 41→      console.error("Failed to log email ingest:", e);
 42→    }
 43→    return new Response(JSON.stringify(responseBody), {
 44→      status,
 45→      headers: { ...corsHeaders, "Content-Type": "application/json" },
 46→    });
 47→  };
 48→
 49→  try {
 50→    // Check global email ingestion toggle
 51→    const { data: config } = await supabase
 52→      .from("platform_config")
 53→      .select("email_ingestion_enabled")
 54→      .limit(1)
 55→      .single();
 56→
 57→    if (config && !config.email_ingestion_enabled) {
 58→      return await logAndRespond(403, { status: "rejected", error_message: "Email ingestion globally disabled" }, { error: "Email ingestion is globally disabled" });
 59→    }
 60→
 61→    // Parse incoming payload — support Postmark JSON, legacy JSON, and multipart/form-data
 62→    let sender: string | null = null;
 63→    let recipient: string | null = null;
 64→    const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
 65→
 66→    const contentType = req.headers.get("content-type") || "";
 67→
 68→    if (contentType.includes("application/json")) {
 69→      const body = await req.json();
 70→
 71→      // Postmark inbound webhook format
 72→      if (body.FromFull || body.ToFull || body.Attachments) {
 73→        // Postmark format
 74→        sender = body.FromFull?.Email || body.From ? extractEmail(body.From) : null;
 75→
 76→        // ToFull is an array in Postmark
 77→        if (body.ToFull && Array.isArray(body.ToFull) && body.ToFull.length > 0) {
 78→          recipient = body.ToFull[0].Email?.toLowerCase() || null;
 79→        } else if (body.To) {
 80→          recipient = extractEmail(body.To);
 81→        }
 82→
 83→        // Postmark attachments: array of { Name, Content (base64), ContentType, ContentLength }
 84→        if (body.Attachments && Array.isArray(body.Attachments)) {
 85→          for (const att of body.Attachments) {
 86→            if (!att.Name || !att.Content) continue;
 87→            // Only accept PDF and DOCX
 88→            const name = att.Name.toLowerCase();
 89→            if (!name.endsWith(".pdf") && !name.endsWith(".docx")) continue;
 90→            const fileContent = Uint8Array.from(atob(att.Content), (c: string) => c.charCodeAt(0));
 91→            attachmentFiles.push({ filename: att.Name, content: fileContent });
 92→          }
 93→        }
 94→      } else {
 95→        // Legacy JSON format (backward compatible)
 96→        sender = body.sender || null;
 97→        recipient = body.recipient || null;
 98→
 99→        if (body.attachments && Array.isArray(body.attachments)) {
100→          for (const att of body.attachments) {
101→            if (!att.filename || !att.content) continue;
102→            const fileContent = Uint8Array.from(atob(att.content), (c: string) => c.charCodeAt(0));
103→            attachmentFiles.push({ filename: att.filename, content: fileContent });
104→          }
105→        }
106→      }
107→    } else if (contentType.includes("multipart/form-data")) {
108→      // SendGrid/Mailgun multipart format (backward compatible)
109→      const formData = await req.formData();
110→
111→      const envelope = formData.get("envelope") as string | null;
112→      const fromField = formData.get("from") as string | null;
113→      const toField = formData.get("to") as string | null;
114→
115→      // Parse sender
116→      if (envelope) {
117→        try {
118→          const env = JSON.parse(envelope);
119→          if (env.from) sender = extractEmail(env.from);
120→        } catch { /* ignore */ }
121→      }
122→      if (!sender && fromField) sender = extractEmail(fromField);
123→
124→      // Parse recipient
125→      if (envelope) {
126→        try {
127→          const env = JSON.parse(envelope);
128→          if (env.to && Array.isArray(env.to) && env.to.length > 0) recipient = extractEmail(env.to[0]);
129→        } catch { /* ignore */ }
130→      }
131→      if (!recipient && toField) recipient = extractEmail(toField.split(",")[0]);
132→
133→      // Extract attachments
134→      const attachmentCount = parseInt(formData.get("attachments") as string || "0", 10);
135→      for (let i = 1; i <= Math.max(attachmentCount, 10); i++) {
136→        const file = formData.get(`attachment${i}`) as File | null;
137→        if (!file) continue;
138→        const buffer = await file.arrayBuffer();
139→        attachmentFiles.push({
140→          filename: file.name || `attachment_${i}`,
141→          content: new Uint8Array(buffer),
142→        });
143→      }
144→
145→      // Fallback: check for "attachment-info" pattern
146→      if (attachmentFiles.length === 0) {
147→        for (const [key, value] of formData.entries()) {
148→          if (key.startsWith("attachment") && value instanceof File) {
149→            const buffer = await value.arrayBuffer();
150→            attachmentFiles.push({
151→              filename: value.name || key,
152→              content: new Uint8Array(buffer),
153→            });
154→          }
155→        }
156→      }
157→    } else {
158→      return await logAndRespond(400, { status: "error", error_message: "Unsupported content type" }, { error: "Unsupported content type" });
159→    }
160→
161→    if (!recipient) {
162→      return await logAndRespond(400, { sender, recipient, status: "error", error_message: "No recipient" }, { error: "No recipient" });
163→    }
164→
165→    // Step 1: Try per-job routing — match recipient against jobs.inbox_email
166→    let jobId: string | null = null;
167→    let userId: string | null = null;
168→
169→    const { data: jobMatch } = await supabase
170→      .from("jobs")
171→      .select("id, user_id")
172→      .eq("inbox_email", recipient)
173→      .single();
174→
175→    if (jobMatch) {
176→      jobId = jobMatch.id;
177→      userId = jobMatch.user_id;
178→    }
179→
180→    // Step 2: Fall back to user-level inbox routing
181→    if (!userId) {
182→      // Strip +tag for matching: abc+xyz@domain → abc@domain
183→      const baseRecipient = recipient.replace(/\+[^@]*@/, "@");
184→
185→      const { data: profile } = await supabase
186→        .from("profiles")
